result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/reconcile.py", "content": """"Bank reconciliation matcher.

Compares a bank statement (date, amount, memo) against a ledger
(date, amount, payee, check_no):

  * Exact match  : identical amount AND statement date within +/- WINDOW_DAYS
                   of the ledger date. Each item is consumed at most once.
  * Transposition: among the leftovers, an unmatched ledger item and an
                   unmatched bank item whose amounts become equal after
                   swapping any two digits (e.g. 843.75 <-> 834.75).

reconcile() returns:
  {
    "matches":                  [{"ledger": ..., "bank": ..., "date_delta": n}],
    "unmatched_ledger":         [ledger rows never matched],
    "unmatched_bank":           [bank rows never matched],
    "suspected_transpositions": [{"ledger": ..., "bank": ...}]
  }

Accounting convention for transpositions: the money movement demonstrably
happened (the bank processed it), only the book amount was recorded wrong.
The bank-side line is therefore linked via suspected_transpositions and
excluded from unmatched_bank, while the incorrect ledger entry stays in
unmatched_ledger so it can be corrected in the books.
"""

from collections import defaultdict
from datetime import date

WINDOW_DAYS = 3


def to_cents(amount):
    """Float dollars -> integer cents (avoids float equality issues)."""
    return int(round(round(float(amount), 2) * 100))


def parse_date(s):
    return date.fromisoformat(s)


def _digit_swaps(s):
    """All strings reachable by swapping exactly two distinct digit positions."""
    out = set()
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            if s[i] != s[j]:
                t = list(s)
                t[i], t[j] = t[j], t[i]
                out.add("".join(t))
    return out


def is_transposition(amount_a, amount_b):
    """True if the cent-string of one amount is a two-digit swap of the other."""
    a, b = str(to_cents(amount_a)), str(to_cents(amount_b))
    return a != b and b in _digit_swaps(a)


def reconcile(statement, ledger):
    bank = [
        {"row": r, "cents": to_cents(r["amount"]), "date": parse_date(r["date"])}
        for r in statement
    ]
    book = [
        {"row": r, "cents": to_cents(r["amount"]), "date": parse_date(r["date"])}
        for r in ledger
    ]

    by_amount = defaultdict(list)
    for idx, b in enumerate(bank):
        by_amount[b["cents"]].append(idx)

    used_bank = set()
    matches = []
    unmatched_book = []

    # Pass 1 -- exact amount within the date window, nearest date wins,
    # ties broken by statement order => deterministic.
    for l in book:
        best = None
        for idx in by_amount.get(l["cents"], ()):
            if idx in used_bank:
                continue
            delta = abs((l["date"] - bank[idx]["date"]).days)
            if delta > WINDOW_DAYS:
                continue
            key = (delta, idx)
            if best is None or key < best[0]:
                best = (key, idx)
        if best is None:
            unmatched_book.append(l)
        else:
            idx = best[1]
            used_bank.add(idx)
            matches.append({
                "ledger": l["row"],
                "bank": bank[idx]["row"],
                "date_delta": (l["date"] - bank[idx]["date"]).days,
            })

    leftover_bank = [b for i, b in enumerate(bank) if i not in used_bank]

    # Pass 2 -- transposition detection among leftovers (same date window).
    suspected = []
    claimed_bank = set()
    for l in unmatched_book:
        for b in leftover_bank:
            if id(b) in claimed_bank:
                continue
            if abs((l["date"] - b["date"]).days) > WINDOW_DAYS:
                continue
            if is_transposition(l["cents"], b["cents"]):
                suspected.append({"ledger": l["row"], "bank": b["row"]})
                claimed_bank.add(id(b))
                break

    transposed_bank_ids = {s["bank"]["id"] for s in suspected}
    unmatched_bank = [b["row"] for b in leftover_bank
                      if b["row"]["id"] not in transposed_bank_ids]

    return {
        "matches": matches,
        "unmatched_ledger": [l["row"] for l in unmatched_book],
        "unmatched_bank": unmatched_bank,
        "suspected_transpositions": suspected,
    }


if __name__ == "__main__":
    import gen_data

    data = gen_data.generate(write_csv=False)
    res = reconcile(data["statement"], data["ledger"])
    print(f"matched pairs             : {len(res['matches'])}")
    print(f"unmatched ledger ({len(res['unmatched_ledger']):2d})     : "
          f"{[r['id'] for r in res['unmatched_ledger']]}")
    print(f"unmatched bank ({len(res['unmatched_bank']):2d})         : "
          f"{[r['id'] for r in res['unmatched_bank']]}")
    print("suspected transpositions  :")
    for s in res["suspected_transpositions"]:
        print(f"    ledger {s['ledger']['amount']} ({s['ledger']['id']}) vs "
              f"bank {s['bank']['amount']} ({s['bank']['id']})")
"})
print(result)

